"""Character-costume families: fursuit/mascot, cosplay (original), LARP, faire, reenactment, sci-fi/fantasy, drag/stage. Files costume_char_*. Garment/costume descriptions only; original designs, no franchises."""
import os, re, sys, random, zlib
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
from paths import FINAL
def S(x): return [i.strip() for i in x.split(';') if i.strip()]
def R(*k): return random.Random(zlib.crc32('|'.join(map(str, k)).encode()))
ANIMAL = S("fox; wolf; cat; dog; rabbit; deer; bear; raccoon; otter; tiger; lion; dragon; horse; bird of prey; owl; raven; squirrel; skunk; badger; lizard; shark; seal; panda; cheetah; goat; sheep; hyena; kangaroo; bat; frog; mouse; hedgehog; ferret; crocodile; peacock; moth; jellyfish; axolotl; capybara; platypus; red panda; snow leopard; lynx; coyote; moose; elephant; giraffe; dolphin; octopus")
FURMAKE = S("a full-body fursuit of long faux fur with a large sculpted foam head, hinged jaw, and glass-bright eyes; a partial fursuit with head, paws and tail only; a digitigrade fursuit with padded stilt-style hind legs; a quadsuit built for walking on all fours; a toony fursuit with an oversized rounded head and big painted eyes; a realistic fursuit with airbrushed shading and sculpted muzzle; a kemono-style fursuit with flat painted eyes and a small nose; a fursuit head only with an attached mane; a plush mascot suit with a fixed smile; a sports-mascot suit with an oversized fixed head and team-coloured jersey; a mascot suit with an internal cooling fan; a fursuit with LED-lit eyes and glowing tail tip; a fursuit with a removable tail and clip-on paws; a fursuit with raised mane, long ears and expressive moving ears; a painted-foam bodysuit over a padded undersuit")
FURSET = S("pawpads in contrasting colour; a fluffy tail the length of the body; a ruff of longer fur at the neck; a bandana in the suit's colours; a matching collar tag; a badge or lanyard; digitigrade foot extensions; clawed gloves; a fur-trimmed vest; tinted visor eyes; an airbrushed muzzle; a fan-cooled head; felt-lined paws; a belt pouch; a shawl made of faux fur; a patterned underbelly; markings painted on the cheeks")
COSBASE = S("an original sci-fi pilot with a padded flight jacket and goggles; an original fantasy knight with layered plate and a heraldic tabard; an original mage with a patterned robe and a staff; an original rogue in a hooded cloak and leather vest; an original witch in a patched dress and pointed hat; an original space explorer in a bulky suit with a glass helmet; an original cyberpunk courier in a neon-trimmed jacket and a visor; an original steampunk inventor with a brass goggled top hat and a leather corset; an original pirate captain in a long coat and wide hat; an original vampire noble in a high-collared cape; an original forest spirit wearing leaves and antlers; an original angel with wide feathered wings and a flowing robe; an original demon with horns and a spiked tail; an original robot with plated limbs; an original post-apocalypse survivor in patched layers; an original sea creature with fins and iridescent scales; an original samurai-inspired warrior in lacquered plates; an original desert nomad in layered wraps; an original dragon rider in scaled armour; an original bard in a patchwork coat holding a lute")
COSMAT = S("worbla and EVA foam painted with a metallic finish; thermoplastic armour with weathered paint; 3D-printed armour sanded and primed; cotton and satin sewn patterns; real leather tooled and stitched; chainmail rings in aluminum; faux fur panels; resin-cast props; LED strips and wiring in the costume; foam with battle damage and mud effects; fibreglass shell pieces; embroidered silk panels; a wig styled with spray and wire; coloured contact lenses; prosthetic ears; a hand-painted cape; reflective vinyl panels")
CRAFT = S("a beginner-made costume with visible glue and uneven seams; a competition-grade costume with flawless finish; a convention-ready costume with wired parts; a budget thrifted costume; a heavily weathered costume; a clean pristine costume; a half-finished costume with exposed foam; a group costume matching the rest of a party; a costume with working lights and sound; a costume built to survive a long day on foot")
LARP = S("a padded foam sword and shield for safe combat play; a tabard bearing a team crest; a belt with pouches for tokens, potions and cards; leather bracers; a hooded cloak in the faction colours; a rope belt; a quilted gambeson; a coif; a chainmail shirt; a set of foam armour plates; a leather jerkin; a healer's apron with vials; a scout's camouflage cloak; a noble's brocade coat; a necromancer's robe with bone trim; a priest's vestments; a ranger's bow and quiver; a bard's instrument; a scroll case; a guild badge; face paint for a tribe; horns for a monster race; prosthetic ears for an elf; a tail for a beast-folk; a dwarf's braided beard; a monster mask; a mage's staff with LED; a fur mantle; a faction banner; a fantasy coin pouch; a soft-hide boot cover")
FAIRE = S("a laced bodice over a chemise with a full skirt; a corseted gown with a ruffled collar; a linen shirt with laced cuffs and a leather vest; a doublet with slashed sleeves; a tunic with a belt and pouch; a hooded cloak over a tunic; a floral wreath headpiece; a pirate coat with a feathered hat; a fairy costume with wings; a tavern wench dress; a knight's surcoat; a monk's habit; a jester's motley with bells; a friar's robe; a gypsy-style skirt with coins; a renaissance noble's brocade gown; a pageboy outfit; a yeoman's leather jerkin; a leather armour cuirass; a mermaid tail; a jewelled circlet; a velvet cap; a turkey-leg-carrying visitor outfit")
REENACT = S("a Roman legionary kit with segmented armour; a Viking raider's mail and shield; a Napoleonic infantry uniform; a Civil War-era soldier's wool uniform; a Victorian lady's walking dress; a medieval peasant's tunic and hose; a Tudor noble's gown; a Georgian gentleman's frock coat; an Edwardian lady's tea gown; a Regency empire-waist dress; a 1920s flapper dress; a Wild West gunslinger's duster and hat; a WWII infantry uniform; a WWII factory worker's coverall; a WWI trench uniform; a medieval knight's full harness; a Mongol warrior's lamellar; a samurai's armour; a Greek hoplite's bronze kit; an Egyptian linen kilt and collar; an Aztec warrior's feathered cloak; a Zulu warrior's shield and beads; a Bedouin trader's robes; a Celtic chieftain's cloak; a Napoleonic officer's bicorn hat")
SCIFI = S("a skin-tight space suit with a glowing chest panel; a cyber-visor with trailing wires; a mechanical arm gauntlet with LEDs; a hover-boot with light strips; a metallic jumpsuit with circuit patterns; a bio-luminescent cloak; an alien bodysuit with textured scales; an exo-suit with hydraulics; a time-traveller's coat with brass gadgets; an interstellar trader's layered coat; a gas-mask and rebreather; a holographic jacket; a plasma-blade belt; a utility harness with vials; a lab coat with glowing vials; a hacker's hoodie with LED circuits; a power-armour shell; a neon trench coat; a laser tag vest; a glowing wing pack; a telepath's headband; a floating holo-tablet cuff; a laser-etched mask")
FANT = S("an elven gown with leaf embroidery and long trailing sleeves; a dwarf's heavy leather apron with tool loops; a mermaid-scale bodice; a faerie wing set with delicate veins; a dragon-scale cloak; a wizard's star-spangled robe; a druid's antler crown and moss cloak; a unicorn horn headdress; a phoenix feather train; a centaur harness; a satyr's goat horns and fur legs; a banshee's tattered white gown; a nymph's vine-wrapped gown; a goblin's patched leather; an ogre's spiked shoulder pad; a lich's bone crown and tattered robe; a troll's mossy mask; a siren's pearl-trimmed gown; a fire-spirit gown of orange and red layers; a frost queen's ice crown and cape; an ent's bark-textured suit; a witch king's iron crown")
DRAG = S("an oversized sequin gown with a dramatic train; a feathered showgirl-style outfit with a huge headdress; a bodysuit covered in rhinestones; a big structured wig in a bright colour; padded hips and a cinched corset; a statement bodice with 3D flowers; a tuxedo-style suit in satin; a Elizabethan ruff and wide-hooped gown; a latex catsuit with metal fittings; a sparkly cabaret jacket and tails; a bold pantsuit with huge shoulders; exaggerated eyelashes; sky-high platform boots; long opera gloves; an avant-garde sculptural costume; a costume made entirely from recycled materials; a pop-star-inspired jumpsuit; a vintage Hollywood glamour gown; a clown-queen look with huge ruffles; a king look with a bold beard and a velvet coat; a stage-ready tear-away outfit; a lip-sync reveal costume that changes with a pull")
def mk():
    G = {}
    G['costume_char_fursuit'] = sorted({f"{a} -- {m}" for a in ANIMAL for m in FURMAKE if R('fs', a, m).random() < .40})
    G['costume_char_fursuit_animal'] = ANIMAL; G['costume_char_fursuit_build'] = FURMAKE; G['costume_char_fursuit_detail'] = FURSET
    G['costume_char_cosplay'] = sorted({f"{b}, built with {m}; {c}" for b in COSBASE for m in COSMAT for c in CRAFT if R('cs', b, m, c).random() < .06})
    G['costume_char_cosplay_character'] = COSBASE; G['costume_char_cosplay_material'] = COSMAT; G['costume_char_cosplay_craft'] = CRAFT
    G['costume_char_larp'] = LARP; G['costume_char_faire'] = FAIRE; G['costume_char_reenact'] = REENACT
    G['costume_char_scifi'] = SCIFI; G['costume_char_fantasy'] = FANT; G['costume_char_drag'] = DRAG
    G['costume_char_prompt'] = ['Costume: __costume_char_cosplay__.', 'A fursuit: __costume_char_fursuit__, with __costume_char_fursuit_detail__.', 'Live-action roleplay kit: __costume_char_larp__.', 'Faire costume: __costume_char_faire__.', 'Historical reenactment kit: __costume_char_reenact__.', 'Sci-fi costume: __costume_char_scifi__.', 'Fantasy costume: __costume_char_fantasy__.', 'Stage or drag costume: __costume_char_drag__.']
    return G
def build(): return mk()
def run(final):
    G = build()
    for n, l in G.items():
        assert l and all(l) and not any(c in x for x in l for c in '{}|'), n
        open(os.path.join(final, n + '.txt'), 'w', encoding='utf8', newline='\n').write('\n'.join(dict.fromkeys(l)) + '\n')
    print('character costumes:', len(G), 'files'); return G
def export_aoo(out, prefix='aoo_'):
    G = build(); names_ = set(G); ref = re.compile(r'__([A-Za-z0-9_\-/]+)__'); n = 0
    for name, lines in G.items():
        keep = list(dict.fromkeys(ref.sub(lambda m: '__' + prefix + m.group(1) + '__' if m.group(1) in names_ else m.group(0), l) for l in lines))
        if name != 'costume_char_prompt': random.Random(zlib.crc32(name.encode())).shuffle(keep)
        open(os.path.join(out, prefix + name + '.txt'), 'w', encoding='utf8', newline='\n').write('\n'.join(keep) + '\n'); n += 1
    return n
if __name__ == '__main__':
    a = [x for x in sys.argv[1:] if os.path.isdir(x)]; run(os.path.abspath(a[0]) if a else FINAL)
